@Serializable data class Movie(val title: String, val year: Int)

install(ContentNegotiation) { json(); xml() }

routing {
    get("/movies/{id}") {
        val movie = store.find(call.parameters["id"]!!)   // one model
        if (movie == null) call.respond(HttpStatusCode.NotFound)
        else call.respond(movie)                          // JSON or XML by Accept
    }
}
